//! 🔡️ Admitted Unicode records, bidi levels, canonical normalization and grapheme clusters agree with the original corpus through funded close.
use super::*;
use semio_framework_2d_text_font::*;
use semio_framework_2d_text_font_testing::{close};
#[global_allocator]
static FONT_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
#[test]
fn font_shape_bidi_original_scalar_levels_and_physical_candidates(){use crate::{*,bidi::*,normalize::NormalizedScalar};let rows:serde_json::Value=serde_json::from_str(include_str!("../↔️bidi/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut admission=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while !admission.advance(4096).unwrap().done{}let data=admission.take_result().unwrap();let data_pointer=data.source.as_ptr();for row in rows.as_array().unwrap(){let text=row["text"].as_str().unwrap();let source=semio_framework_value::list::PagedList::<_,{usize::MAX}>::try_from_iter(text.char_indices().map(|(source_at,scalar)|NormalizedScalar{scalar:scalar as u32,source_at,combining_class:0})).unwrap();let pointer=source.get(0).map(|value|value as*const NormalizedScalar);let direction=match row["direction"].as_str().unwrap(){"auto"=>UnicodeBidiDirection::Auto,"ltr"=>UnicodeBidiDirection::LeftToRight,"rtl"=>UnicodeBidiDirection::RightToLeft,_=>panic!("Unauthored direction")};for grant in [1,7,4096]{let mut cursor=UnicodeBidiCursor::new(data.layout,&data.source,&source,direction,262144,1000000000);let mut work=0;loop{let(p,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&data.source,&source,grant).unwrap());assert!(!physical.overflowed);assert_eq!(physical.released_bytes,0);assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let pointer=cursor.result().unwrap().levels.get(0).map(|value|value as*const u8);let(output,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.take_result().unwrap());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(output.levels.get(0).map(|value|value as*const u8),pointer);let indices=row["indices"].as_array().unwrap();assert_eq!(indices.iter().map(|value|u64::from(*output.levels.get(value.as_u64().unwrap()as usize).unwrap())).collect::<Vec<_>>(),row["levels"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()).collect::<Vec<_>>(),"{} grant={grant}",row["name"]);assert_eq!(output.order.iter().map(|value|*value as u64).collect::<Vec<_>>(),row["order"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()).collect::<Vec<_>>(),"{} grant={grant}",row["name"]);if let Some(mirrors)=row["mirrors"].as_array(){assert_eq!(output.mirrors.iter().map(|value|[value.at as u64,u64::from(value.scalar)]).collect::<Vec<_>>(),mirrors.iter().map(|value|[value[0].as_u64().unwrap(),value[1].as_u64().unwrap()]).collect::<Vec<_>>());}close(cursor);close(output);}for stop in [0,1,2,7,20,40,100]{let mut cursor=UnicodeBidiCursor::new(data.layout,&data.source,&source,direction,262144,1000000000);if stop>0{cursor.advance(&data.source,&source,stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);assert_eq!(source.get(0).map(|value|value as*const NormalizedScalar),pointer);assert_eq!(data.source.as_ptr(),data_pointer);}close(source);}close(admission);close(data);}
#[test]
fn font_shape_unicode_original_records_and_physical_source(){use crate::*;let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let provenance:serde_json::Value=serde_json::from_str(include_str!("../📦️data/🔣️provenance.json")).unwrap();for grant in [1,7,4096]{let source=UNICODE_BYTES.to_vec();let pointer=source.as_ptr();let capacity=source.capacity();let mut admission=UnicodeDataAdmissionJob::new(source,1000000);let mut work=0;loop{let p=admission.advance(grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(admission.result().is_err());}let data=admission.take_result().unwrap();assert_eq!(data.source.as_ptr(),pointer);for row in corpus["properties"].as_array().unwrap(){let mut cursor=UnicodePropertyCursor::new(data.layout,row["scalar"].as_u64().unwrap()as u32).unwrap();while !cursor.step(&data.source).unwrap(){}let property=cursor.result().unwrap();assert_eq!(provenance["categories"][usize::from(property.category)],row["category"]);assert_eq!(provenance["bidiClasses"][usize::from(property.bidi)],row["bidi"]);assert_eq!(u64::from(property.combining_class),row["combiningClass"].as_u64().unwrap());close(cursor);}let r=FontReader::whole(&data.source);for row in corpus["compositions"].as_array().unwrap(){let mut cursor=UnicodeMappingCursor::new(data.layout,UnicodeMapping::Composition,row["first"].as_u64().unwrap()as u32,row["second"].as_u64().unwrap()as u32);while !cursor.step(&data.source).unwrap(){}assert_eq!(u64::from(r.u32(cursor.result().unwrap().unwrap()+8).unwrap()),row["result"].as_u64().unwrap());close(cursor);}for row in corpus["decompositions"].as_array().unwrap(){let mut cursor=UnicodeMappingCursor::new(data.layout,UnicodeMapping::Decomposition,row["scalar"].as_u64().unwrap()as u32,0);while !cursor.step(&data.source).unwrap(){}let at=cursor.result().unwrap().unwrap();let first=r.u32(at+4).unwrap()as usize;let count=r.u32(at+8).unwrap()as usize;assert_eq!((0..count).map(|index|u64::from(r.u32(data.layout.offsets[3]+(first+index)*4).unwrap())).collect::<Vec<_>>(),row["values"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()).collect::<Vec<_>>());assert_eq!(r.u32(at+12).unwrap()!=0,row["compatibility"].as_bool().unwrap());close(cursor);}close(admission);assert!(close(data)>=capacity);}for stop in [0,1,2,7,20,100,20000]{let source=UNICODE_BYTES.to_vec();let capacity=source.capacity();let mut job=UnicodeDataAdmissionJob::new(source,1000000);if stop>0{job.advance(stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||job.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(job.result().is_err());assert!(close(job)>=capacity);}}
#[test]
fn font_shape_canonical_normalization_preserves_shared_utf8_clusters(){use crate::{*,normalize::*};let rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️normalize/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut admission=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while !admission.advance(4096).unwrap().done{}let data=admission.take_result().unwrap();let pointer=data.source.as_ptr();for row in rows.as_array().unwrap(){for grant in [1,7,4096]{let text=row["text"].as_str().unwrap().to_string();let text_pointer=text.as_ptr();let mut cursor=UnicodeNormalizationCursor::new(data.layout,&data.source,&text,1048576,1000000000);let mut work=0;loop{let p=cursor.advance(&data.source,&text,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let output=cursor.take_result().unwrap();assert_eq!(output.iter().map(|value|u64::from(value.scalar)).collect::<Vec<_>>(),row["scalars"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()).collect::<Vec<_>>());assert_eq!(output.iter().map(|value|value.source_at as u64).collect::<Vec<_>>(),row["clusters"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()).collect::<Vec<_>>());assert_eq!(data.source.as_ptr(),pointer);assert_eq!(text.as_ptr(),text_pointer);close(cursor);close(output);close(text);}}let text="A\u{0308} a\u{0315}\u{0300} 👩‍💻".to_string();for stop in [0,1,2,7,20,100,1000]{let mut cursor=UnicodeNormalizationCursor::new(data.layout,&data.source,&text,1048576,1000000000);if stop>0{cursor.advance(&data.source,&text,stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);assert_eq!(data.source.as_ptr(),pointer);}close(text);close(admission);close(data);}
#[test]
fn font_shape_grapheme_original_boundaries_and_physical_candidates(){use crate::{*,cluster::*,normalize::NormalizedScalar};let rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️cluster/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut admission=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while !admission.advance(4096).unwrap().done{}let data=admission.take_result().unwrap();for row in rows.as_array().unwrap(){let text=row["text"].as_str().unwrap();let source=semio_framework_value::list::PagedList::<_,{usize::MAX}>::try_from_iter(text.char_indices().map(|(source_at,scalar)|NormalizedScalar{scalar:scalar as u32,source_at,combining_class:0})).unwrap();let pointer=source.get(0).map(|value|value as*const NormalizedScalar);for grant in [1,7,4096]{let mut cursor=UnicodeGraphemeCursor::new(data.layout,&data.source,&source,1000000000);let mut work=0;loop{let p=cursor.advance(&data.source,&source,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let output=cursor.take_result().unwrap();assert_eq!(output.iter().map(|value|[value.start as u64,value.end as u64]).collect::<Vec<_>>(),row["clusters"].as_array().unwrap().iter().map(|value|[value[0].as_u64().unwrap(),value[1].as_u64().unwrap()]).collect::<Vec<_>>());assert_eq!(source.get(0).map(|value|value as*const NormalizedScalar),pointer);close(cursor);close(output);}for stop in [0,1,2,7,20,100,1000]{let mut cursor=UnicodeGraphemeCursor::new(data.layout,&data.source,&source,1000000000);if stop>0{cursor.advance(&data.source,&source,stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);assert_eq!(source.get(0).map(|value|value as*const NormalizedScalar),pointer);}close(source);}close(admission);close(data);}
